    for code, name, description, dependencies, sort_order in DEFAULT_MODULES:
        module_model.objects.using(schema_editor.connection.alias).get_or_create(
            code=code,
            defaults={
                'name': name,
                'description': description,
                'dependencies': dependencies,
                'sort_order': sort_order,
            },
        )


